<?php
declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../admin/includes/auth.php';
$db=db();$pkStmt=$db->query("SHOW KEYS FROM projects WHERE Key_name='PRIMARY'");$pkRow=$pkStmt?$pkStmt->fetch():false;$projectPk=$pkRow['Column_name']??'id';if(!preg_match('/^[A-Za-z_][A-Za-z0-9_]*$/',$projectPk))$projectPk='id';
$id=(int)($_GET['id']??$_POST['id']??0);$errors=[];$project=['title'=>'','slug'=>'','category'=>'','client_name'=>'','industry'=>'','project_type'=>'','project_duration'=>'','project_scope'=>'','objectives'=>'','short_description'=>'','challenge'=>'','strategy'=>'','solution'=>'','key_features'=>'','results'=>'','technologies'=>'','featured_image'=>'','gallery'=>'','live_url'=>'','github_url'=>'','meta_title'=>'','meta_description'=>'','is_featured'=>0,'is_published'=>1];
if($id){$stmt=$db->prepare("SELECT * FROM projects WHERE `{$projectPk}`=? LIMIT 1");$stmt->execute([$id]);$found=$stmt->fetch();if($found)$project=array_merge($project,array_map(static fn($v)=>$v??'',$found));}
if($_SERVER['REQUEST_METHOD']==='POST'){foreach(array_keys($project) as $key){if(isset($_POST[$key]))$project[$key]=is_string($_POST[$key])?trim($_POST[$key]):$_POST[$key];}$project['is_featured']=isset($_POST['is_featured'])?1:0;$project['is_published']=isset($_POST['is_published'])?1:0;if($project['title']===''||$project['category']===''||$project['short_description']==='')$errors[]='Title, category and short description are required.';if($project['slug']==='')$project['slug']=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$project['title']),'-'));if($project['gallery']!==''){json_decode($project['gallery'],true);if(json_last_error()!==JSON_ERROR_NONE)$errors[]='Gallery must be valid JSON.';}if(!$errors){$fields=['title','slug','category','client_name','industry','project_type','project_duration','project_scope','objectives','short_description','challenge','strategy','solution','key_features','results','technologies','featured_image','gallery','live_url','github_url','meta_title','meta_description','is_featured','is_published'];$set=implode(',',array_map(fn($f)=>'`'.$f.'`=?',$fields));$values=array_map(fn($f)=>$project[$f],$fields);if($id){$db->prepare("UPDATE projects SET $set WHERE `{$projectPk}`=?")->execute([...$values,$id]);}else{$db->prepare('INSERT INTO projects (`'.implode('`,`',$fields).'`) VALUES ('.implode(',',array_fill(0,count($fields),'?')).')')->execute($values);}$targetId=$id?:(int)$db->lastInsertId();header('Location: project-form.php?id='.$targetId.'&saved=1');exit;}}
$esc=static fn($v):string=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$gallery=[];$decoded=json_decode((string)$project['gallery'],true);if(is_array($decoded))$gallery=array_values(array_filter($decoded,'is_string'));?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $id?'Edit':'Add' ?> Project | Case Study</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>.media-preview{width:100%;height:220px;object-fit:cover;border-radius:14px;background:#eef2f7}.gallery-thumb{height:130px;width:100%;object-fit:cover;border-radius:12px}</style></head><body class="bg-light"><main class="container py-5" style="max-width:1100px"><div class="d-flex justify-content-between mb-4"><div><h1 class="h2 mb-1"><?= $id?'Edit':'Add' ?> Project</h1><p class="text-muted mb-0">Build and manage a complete portfolio case study.</p></div><a href="projects.php" class="btn btn-outline-secondary">Back</a></div><?php if(isset($_GET['saved'])):?><div class="alert alert-success">Project saved successfully.</div><?php endif;?><?php foreach($errors as $e):?><div class="alert alert-danger"><?=$esc($e)?></div><?php endforeach;?><form method="post" class="card border-0 shadow-sm p-4"><input type="hidden" name="id" value="<?=$id?>"><h2 class="h5 border-bottom pb-2">Project Basics</h2><div class="row g-3 mb-4"><div class="col-md-8"><label class="form-label">Title</label><input name="title" class="form-control" value="<?=$esc($project['title'])?>" required></div><div class="col-md-4"><label class="form-label">Category</label><input name="category" class="form-control" value="<?=$esc($project['category'])?>" required></div><div class="col-md-8"><label class="form-label">Slug</label><input name="slug" class="form-control" value="<?=$esc($project['slug'])?>"></div><div class="col-md-4"><label class="form-label">Project Type</label><input name="project_type" class="form-control" value="<?=$esc($project['project_type'])?>"></div><div class="col-md-4"><label class="form-label">Client / Brand</label><input name="client_name" class="form-control" value="<?=$esc($project['client_name'])?>"></div><div class="col-md-4"><label class="form-label">Industry</label><input name="industry" class="form-control" value="<?=$esc($project['industry'])?>"></div><div class="col-md-4"><label class="form-label">Duration</label><input name="project_duration" class="form-control" value="<?=$esc($project['project_duration'])?>"></div><div class="col-12"><label class="form-label">Short Description</label><textarea name="short_description" class="form-control" rows="3" required><?=$esc($project['short_description'])?></textarea></div></div><h2 class="h5 border-bottom pb-2">Case Study Story</h2><div class="row g-3 mb-4"><div class="col-md-6"><label class="form-label">Project Scope</label><textarea name="project_scope" class="form-control" rows="5"><?=$esc($project['project_scope'])?></textarea></div><div class="col-md-6"><label class="form-label">Objectives</label><textarea name="objectives" class="form-control" rows="5"><?=$esc($project['objectives'])?></textarea></div><div class="col-md-6"><label class="form-label">Challenge</label><textarea name="challenge" class="form-control" rows="6"><?=$esc($project['challenge'])?></textarea></div><div class="col-md-6"><label class="form-label">Strategy</label><textarea name="strategy" class="form-control" rows="6"><?=$esc($project['strategy'])?></textarea></div><div class="col-md-6"><label class="form-label">Solution</label><textarea name="solution" class="form-control" rows="6"><?=$esc($project['solution'])?></textarea></div><div class="col-md-6"><label class="form-label">Key Features</label><textarea name="key_features" class="form-control" rows="6"><?=$esc($project['key_features'])?></textarea></div><div class="col-12"><label class="form-label">Results / Outcomes</label><textarea name="results" class="form-control" rows="5"><?=$esc($project['results'])?></textarea></div><div class="col-12"><label class="form-label">Technologies</label><input name="technologies" class="form-control" value="<?=$esc($project['technologies'])?>"></div></div><?php if($id):?><h2 class="h5 border-bottom pb-2">Media Manager</h2><div class="row g-4 mb-4"><div class="col-md-6"><label class="form-label fw-semibold">Hero Image</label><?php if($project['featured_image']):?><img src="<?=$esc(app_url($project['featured_image']))?>" class="media-preview mb-2" alt="Hero image"><?php else:?><div class="media-preview d-flex align-items-center justify-content-center text-muted mb-2">No hero image</div><?php endif;?><input type="file" id="heroFile" class="form-control" accept="image/jpeg,image/png,image/webp"><button type="button" class="btn btn-dark mt-2" onclick="uploadImage('hero')">Upload / Replace Hero</button></div><div class="col-md-6"><label class="form-label fw-semibold">Gallery</label><div class="row g-2 mb-2" id="galleryPreview"><?php foreach($gallery as $g):?><div class="col-6"><img src="<?=$esc(app_url($g))?>" class="gallery-thumb" alt="Gallery image"></div><?php endforeach;?></div><input type="file" id="galleryFile" class="form-control" accept="image/jpeg,image/png,image/webp"><button type="button" class="btn btn-dark mt-2" onclick="uploadImage('gallery')">Add Gallery Image</button></div></div><div id="uploadStatus"></div><?php else:?><div class="alert alert-info">Save the project first to enable the image manager.</div><?php endif;?><h2 class="h5 border-bottom pb-2">Media & Links</h2><div class="row g-3 mb-4"><div class="col-md-6"><label class="form-label">Hero Image Path</label><input name="featured_image" class="form-control" value="<?=$esc($project['featured_image'])?>"></div><div class="col-12"><label class="form-label">Gallery JSON</label><textarea name="gallery" class="form-control" rows="3" placeholder='["uploads/projects/1/image.jpg"]'><?=$esc($project['gallery'])?></textarea></div><div class="col-md-6"><label class="form-label">Live URL</label><input name="live_url" class="form-control" value="<?=$esc($project['live_url'])?>"></div><div class="col-md-6"><label class="form-label">GitHub URL</label><input name="github_url" class="form-control" value="<?=$esc($project['github_url'])?>"></div></div><h2 class="h5 border-bottom pb-2">SEO</h2><div class="row g-3 mb-4"><div class="col-md-6"><label class="form-label">Meta Title</label><input name="meta_title" class="form-control" value="<?=$esc($project['meta_title'])?>"></div><div class="col-md-6"><label class="form-label">Meta Description</label><textarea name="meta_description" class="form-control" rows="2"><?=$esc($project['meta_description'])?></textarea></div></div><div class="d-flex gap-4 mb-4"><div class="form-check"><input class="form-check-input" type="checkbox" name="is_featured" id="featured" <?=((int)($project['is_featured']??0)?'checked':'')?>><label class="form-check-label" for="featured">Featured project</label></div><div class="form-check"><input class="form-check-input" type="checkbox" name="is_published" id="published" <?=((int)($project['is_published']??0)?'checked':'')?>><label class="form-check-label" for="published">Published</label></div></div><button class="btn btn-primary btn-lg">Save Project & Case Study</button></form></main><script>async function uploadImage(kind){const input=document.getElementById(kind==='hero'?'heroFile':'galleryFile');if(!input.files.length){alert('Select an image first.');return;}const fd=new FormData();fd.append('project_id','<?=$id?>');fd.append('kind',kind);fd.append('image',input.files[0]);const status=document.getElementById('uploadStatus');status.innerHTML='<div class="alert alert-info mt-3">Uploading...</div>';try{const r=await fetch('upload-project-image.php',{method:'POST',body:fd});const data=await r.json();if(!data.ok)throw new Error(data.error||'Upload failed');status.innerHTML='<div class="alert alert-success mt-3">Image uploaded successfully. Refreshing...</div>';setTimeout(()=>location.reload(),600);}catch(e){status.innerHTML='<div class="alert alert-danger mt-3">'+e.message+'</div>';}}</script></body></html>